using System.Linq;using UnityEngine;using UnityEditor;using Codice.Characters;
public static class OptimizeSoulsModels{
 public static string Run(){int renderers=0;foreach(PlayerClass role in System.Enum.GetValues(typeof(PlayerClass))){string path="Assets/Resources/Presentation/Classes/"+role+".prefab";var root=PrefabUtility.LoadPrefabContents(path);var groups=root.GetComponentsInChildren<MeshRenderer>().GroupBy(r=>(r.transform.parent,r.sharedMaterial)).ToArray();int index=0;foreach(var group in groups){var parts=group.ToArray();if(parts.Length<2)continue;var parent=group.Key.parent;var mesh=new Mesh{name="Ensamblaje_"+index};mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.CombineMeshes(parts.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=parent.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray());string asset="Assets/Resources/Presentation/Classes/"+role+"/SoulsV2/Ensamblaje_"+(index++)+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(asset);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.uv=mesh.uv;old.RecalculateNormals();old.RecalculateBounds();EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,asset);var go=new GameObject(mesh.name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=group.Key.sharedMaterial;foreach(var part in parts)UnityEngine.Object.DestroyImmediate(part.gameObject);}renderers+=root.GetComponentsInChildren<Renderer>().Length;PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();return "Merged rigid details by bone/material. Renderers total="+renderers;}
}
